drop policy if exists "social_challenge_entries_own_update" on public.social_challenge_entries; create policy "social_challenge_entries_own_update" on public.social_challenge_entries for update to authenticated using ((select auth.uid()) = user_id and exists(select 1 from public.progression_challenges c where c.id=social_challenge_entries.challenge_id and c.enabled=true)) with check ((select auth.uid()) = user_id and completed_at is null and progress >= 0 and exists(select 1 from public.progression_challenges c where c.id=social_challenge_entries.challenge_id and c.enabled=true and progress <= c.target));
